    "sourceVerificationStatus": "PENDING"
  },
  {
    "ruleId": "RULE-IACS-M79-APPLICABILITY",
    "version": 1,
    "titleTr": "Towing winch emergency release uygulanabilirliği",

"titleEn": "Towing winch emergency release applicability",
    "source": {
      "sourceId": "SRC-IACS-M79",
      "locator": "IACS UR M79 Rev.1",
      "authorityLayer": "CLASS_RO",
      "mandatory": true,
      "url": "https://iacs.org.uk/resolutions/unified-requirements/ur-m/ur-m79-rev1-cln"
    },
    "lifecycle": {
      "state": "IN_FORCE",
      "effectiveFrom": "2021-07-01",
      "effectiveTo": null,
      "supersedes": null
    },
    "scope": {
      "modes": [
        "TUG"
      ]
    },
    "when": {
      "all": [
        {
          "field": "context.mode",
          "operator": "EQ",
          "value": "TUG"
        },
        {
          "field": "equipment.towingWinchFitted",
          "operator": "IS_TRUE"
        },
        {
          "field": "class.rulePack.IACS_M79",
          "operator": "IS_TRUE"
        },
        {
          "field": "vessel.contractForConstructionDate",
          "operator": "DATE_GTE",
          "value": "2021-07-01"
        },
        {

"field": "operation.profile",
          "operator": "NOT_IN",
          "value": [
            "SOLELY_LONG_DISTANCE_OCEAN_TOWAGE",
            "ANCHOR_HANDLING"
          ]
        }
      ]
    },
    "then": {
      "result": "APPLICABLE",
      "activate": [
        {
          "type": "FIELD",
          "id": "tug-equipment-readiness.emergency_release_state"
        },
        {
          "type": "FIELD",
          "id": "tug-equipment-readiness.emergency_release_test"
        },
        {
          "type": "CONTROL",
          "id": "CTRL-TUG-ERS"
        },
        {
          "type": "VERIFICATION_GATE",
          "id": "VERIFY-TUG-ERS"
        }
      ],
      "stateEffect": "ERS_REQUIRED",
      "reasonCode": "IACS_M79_ACTIVE"
    },
    "unknownPolicy": "REVIEW_REQUIRED",
    "priority": 650,
    "requiresHumanReview": true,
    "tags": [
      "IACS",
      "TUG",
      "WINCH",
      "ERS"

],
    "exampleOnly": true,
    "publicationStatus": "DRAFT",
    "sourceVerificationStatus": "PENDING"
  },
  {
