      "sourceId": "SRC-STCW",
      "locator": "STCW Chapter V",
      "authorityLayer": "INTERNATIONAL",
      "mandatory": true,
      "url": "https://www.imo.org/en/ourwork/humanelement/pages/stcw-convention.aspx"
    },
    "lifecycle": {
      "state": "IN_FORCE",
      "effectiveFrom": "2012-01-01",
      "effectiveTo": null,
      "supersedes": null
    },
    "scope": {
      "modes": [
        "SHIP"
